// Runs once per server instance (CREATE ... IF NOT EXISTS), so there is no manual migration step.
// Ids are random UUID strings generated by the API. event_logs intentionally has no foreign keys:
// phones may upload taps for a student that was deleted meanwhile, and that must never fail a sync.
export const SCHEMA = `
CREATE TABLE IF NOT EXISTS users (
  id            TEXT PRIMARY KEY,
  student_id    TEXT NOT NULL UNIQUE,            -- login ID: Student ID, or a username for staff/admin
  name          TEXT NOT NULL,
  password_hash TEXT NOT NULL,
  role          TEXT NOT NULL DEFAULT 'student' CHECK (role IN ('student','staff','admin')),
  program       TEXT CHECK (program IN ('BSCS','BSIS')),
  year_level    INTEGER CHECK (year_level BETWEEN 1 AND 4),
  nfc_token     TEXT UNIQUE,                     -- NFC card serial number, e.g. 04A1B2C3D4E5F1
  created_at    TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS files (                -- only used when Vercel Blob is not configured
  id         TEXT PRIMARY KEY,
  data       BYTEA NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS resources (
  id           TEXT PRIMARY KEY,
  title        TEXT NOT NULL,
  description  TEXT NOT NULL DEFAULT '',
  course_code  TEXT NOT NULL,
  program      TEXT NOT NULL CHECK (program IN ('BSCS','BSIS','BOTH')),
  year_level   INTEGER NOT NULL CHECK (year_level BETWEEN 1 AND 4),
  storage_key  TEXT NOT NULL,                    -- 'blob:<pathname>' or 'db:<files.id>'
  content_type TEXT NOT NULL,
  file_name    TEXT NOT NULL,
  file_type    TEXT NOT NULL,                    -- e.g. '.pdf'
  uploader_id  TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  verified     BOOLEAN NOT NULL DEFAULT FALSE,
  verified_by  TEXT REFERENCES users(id) ON DELETE SET NULL,
  score        INTEGER NOT NULL DEFAULT 0,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_resources_score ON resources (score, created_at);

CREATE TABLE IF NOT EXISTS resource_votes (
  resource_id TEXT NOT NULL REFERENCES resources(id) ON DELETE CASCADE,
  user_id     TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  value       INTEGER NOT NULL CHECK (value IN (1, -1)),
  PRIMARY KEY (resource_id, user_id)
);

-- One row per door tap. client_id is generated on the phone so re-sending never duplicates.
CREATE TABLE IF NOT EXISTS event_logs (
  client_id  TEXT PRIMARY KEY,
  student_id TEXT,
  token      TEXT NOT NULL DEFAULT '',
  action     TEXT NOT NULL CHECK (action IN ('CHECK_IN','TEMPORARY_EXIT','RE_ENTRY','UNKNOWN_CARD')),
  scanned_at TIMESTAMPTZ NOT NULL,
  by_id      TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  session_id TEXT                                -- the door session of the tap; NULL for taps from before sessions existed
);
CREATE INDEX IF NOT EXISTS idx_event_logs_student ON event_logs (student_id, scanned_at);
CREATE INDEX IF NOT EXISTS idx_event_logs_time ON event_logs (scanned_at);

-- A door session is one event with its own log: staff create it (draft), optionally import the Google Form
-- registrants, start it (active), scan, and end it (ended). Ended sessions are what the Door log lists.
CREATE TABLE IF NOT EXISTS door_sessions (
  id         TEXT PRIMARY KEY,
  name       TEXT NOT NULL,
  status     TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','active','ended')),
  created_by TEXT REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  started_at TIMESTAMPTZ,
  ended_at   TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_door_sessions_status ON door_sessions (status, created_at);

-- The registration list of a session, imported from the Google Form. student_no is the Student ID as written
-- in the form (normalised). It is matched to a Hub account when read (users.student_id), not when imported, so a
-- student who creates their account after the import is picked up automatically.
CREATE TABLE IF NOT EXISTS door_session_roster (
  session_id TEXT NOT NULL REFERENCES door_sessions(id) ON DELETE CASCADE,
  student_no TEXT NOT NULL,
  form_name  TEXT NOT NULL DEFAULT '',
  PRIMARY KEY (session_id, student_no)
);

-- event_logs.session_id has no foreign key, like the other columns of event_logs, so a late upload from a
-- phone can never fail. (Databases created before sessions get the column from migrate() in db.js.)
CREATE INDEX IF NOT EXISTS idx_event_logs_session ON event_logs (session_id, scanned_at);

-- Change counters. Every write that other open pages should notice bumps one, and pages poll them
-- (GET /api/live) to know when to refresh. Counters avoid comparing timestamps, which is error-prone.
CREATE TABLE IF NOT EXISTS live_state (
  topic   TEXT PRIMARY KEY,
  version INTEGER NOT NULL DEFAULT 0
);

-- Phones (browsers) allowed to sign in by tapping the ID card WITHOUT a password. A card's serial number is
-- not a secret (staff see it in the roster, anyone can read it), so a tap alone is never enough: the browser
-- must also present a random key it was given when the owner confirmed with their password. Only a hash is kept.
CREATE TABLE IF NOT EXISTS card_devices (
  user_id      TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  key_hash     TEXT NOT NULL,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_used_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (user_id, key_hash)
);

-- Login throttling lives in the database because serverless instances do not share memory.
CREATE TABLE IF NOT EXISTS login_attempts (
  bucket   TEXT PRIMARY KEY,
  fails    INTEGER NOT NULL,
  reset_at TIMESTAMPTZ NOT NULL
);
`;
